const CACHE='trame-static-v3';const FILES=["./", "./supports.js", "./index.html", "./core.js", "./render.js", "./icon.svg", "./course.js", "./style.css", "./voice.js", "./manifest.webmanifest", "./app.js", "./storage.js", "./secours/Supports-MJC-a-imprimer.pdf", "./secours/Trame-MJC-animateur.pdf", "./secours/Slides-MJC-secours.pdf", "./assets/mouvement.mp4", "./assets/icon-192.png", "./assets/motif.wav", "./assets/terre-nasa.jpg", "./assets/plat-ia.jpg", "./assets/icon-512.png", "./vendor/PDFJS-LICENSE", "./vendor/pdf.worker.min.mjs", "./vendor/pdf.min.mjs"];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k.startsWith('trame-static')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(caches.match(e.request,{ignoreSearch:true}).then(r=>r||fetch(e.request)))});